import React from 'react';
import { useNavigate, useLocation } from 'react-router-dom';

export type NavItem = {
  id: string;
  label: string;
  path: string;
};

interface NavbarProps {
  sidebarWidth?: number;
  openTabs: NavItem[];
  onCloseTab: (id: string) => void;
}

const Navbar: React.FC<NavbarProps> = ({ sidebarWidth = 280, openTabs }) => {
  const navigate = useNavigate();
  const location = useLocation();

  return (
    <header style={{
      position: 'fixed',
      top: 0,
      left: sidebarWidth,
      right: 0,
      height: 64,
      background: '#ffffff',
      borderBottom: '1px solid #E1E4EA',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'space-between',
      padding: '0 16px',
      boxSizing: 'border-box',
      zIndex: 99,
      transition: 'left 0.25s ease',
    }}>
      {/* Tabs */}
      <nav style={{ display: 'flex', alignItems: 'center', gap: 16, height: '100%' }}>
        {openTabs.map(tab => {
          const isActive = location.pathname === tab.path;
          return (
            <span
              key={tab.id}
              onClick={() => navigate(tab.path)}
              style={{
                fontSize: 14,
                fontWeight: isActive ? 600 : 400,
                color: isActive ? '#0b69ff' : '#4B5565',
                whiteSpace: 'nowrap',
                userSelect: 'none',
                cursor: 'pointer',
              }}
            >
              {tab.label}
            </span>
          );
        })}
      </nav>

      {/* Right: avatar */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
        <div style={{
          width: 36, height: 36, borderRadius: '50%',
          background: '#E1E4EA', display: 'flex',
          alignItems: 'center', justifyContent: 'center',
          fontWeight: 600, fontSize: 14, color: '#4B5565',
        }}>
          U
        </div>
      </div>
    </header>
  );
};

export default Navbar;
